import type {Lang} from "./site-data";
import type {SeoArticle} from "./seo-articles";

type Row=[string,string,string];
type ArticleSeed={slug:string;title:string;description:string;meta:string;sourceNote:string;quickFacts:string[];rows:Row[]};

const evidenceNotes=[
  "Keep the evidence fields separate while you work: source URL, final destination, visible product identity, exact option, displayed price, domestic freight and check time. A blank field is an open question, not permission to copy a value from a similar listing. This record makes a later recheck faster and prevents a spreadsheet snapshot from being mistaken for a current seller promise.",
  "Use three result labels: matched, partial and mismatch. Matched means the destination and required option agree with the saved record. Partial means the product family is plausible but one decision field is missing. Mismatch means the page is dead, redirected to another item or no longer carries the intended choice. Only matched candidates should proceed without another question.",
  "Do not turn price, sales activity, a familiar image or inclusion in an index into a quality claim. Those signals can help prioritize inspection, but they do not prove construction, authenticity, seller service or the condition of the unit that reaches the warehouse. The useful comparison is evidence quality and order readiness, not an unsupported best-product ranking.",
  "Before payment, save the live page and the option text that the ordering flow accepts. If the source cannot be parsed and a manual order is needed, treat every typed field as buyer-supplied. Compare the resulting order summary against the saved record before money moves. A near match is still the wrong instruction when size, color, model or quantity differs.",
  "Write one explicit stop condition for every shortlist. Examples include a missing measurement, an unexplained redirect, a price attached to the wrong quantity tier, an unavailable color or a product identifier that cannot be reconciled. Stopping is a valid research result. It is cheaper than relying on warehouse photos to solve an uncertainty that existed before purchase.",
  "At warehouse arrival, use the saved listing as the reference for QC rather than relying on memory. First confirm identity and option, then inspect condition and the details that matter for use. Request an additional photo or measurement only when it can change the keep-or-return decision, and review the active account promptly because seller eligibility and return timing still apply.",
  "Maintain the page as a dated research route. Reopen high-use links first, follow redirects, compare identity and option structure, and update a checked date only after a real review. If a link changes, label or remove it instead of silently replacing the destination while preserving the old image or product ID. Transparent maintenance is more valuable than a larger but ambiguous list."
];

function make(seed:ArticleSeed):SeoArticle{return{slug:seed.slug,title:seed.title,description:seed.description,meta:seed.meta,sourceNote:seed.sourceNote,quickFacts:seed.quickFacts,sections:seed.rows.map(([heading,a,b],index)=>({heading,paragraphs:[a,b,evidenceNotes[index%evidenceNotes.length]]}))};}

