export const prioritySeoArticleTranslations:Partial<Record<Lang,Record<string,SeoArticle>>>={};
for(const lang of ["de","es","fr","it"] as const){prioritySeoArticleTranslations[lang]=Object.fromEntries(prioritySeoArticles.map(base=>{const seed=localSeeds[lang][base.slug];return[base.slug,{...base,title:seed.title,description:seed.description,meta:localMeta[lang],sourceNote:localSource[lang],quickFacts:seed.quickFacts,sections:localHeadings[lang].map((heading,index)=>({heading,paragraphs:[seed.focus,localNotes[lang][index],index===0?localNotes[lang][6]:localNotes[lang][(index+2)%localNotes[lang].length]]}))}]}));}

